package com.aetherforge.security;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.*;import java.util.*;
@Component public class BearerAuthFilter extends OncePerRequestFilter {private final TokenService tokens;public BearerAuthFilter(TokenService tokens){this.tokens=tokens;}@Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){var user=tokens.resolve(h.substring(7));if(user!=null)SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(user.email(),null,List.of(new SimpleGrantedAuthority("ROLE_"+user.role()))));}chain.doFilter(req,res);}}
